def alphabeta(state, depth, alpha, beta, maximizing):
    if depth == 0 or state.is_terminal():
        return state.evaluate()
    if maximizing:
        value = -float("inf")
        for move in state.moves():
            value = max(value, alphabeta(state.apply(move), depth - 1, alpha, beta, False))
            alpha = max(alpha, value)
            if alpha >= beta:
                break                  # the minimiser would never allow this line
        return value
    value = float("inf")
    for move in state.moves():
        value = min(value, alphabeta(state.apply(move), depth - 1, alpha, beta, True))
        beta = min(beta, value)
        if beta <= alpha:
            break
    return value
